import numpy as np
import control as ctrl
import matplotlib.pyplot as plt
from numpy.polynomial import polynomial as poly
plt.rcParams.update({'font.family':'DejaVu Sans','axes.unicode_minus':False})
w=np.logspace(-4,4,4001);t=np.linspace(0,8,1601)
G=ctrl.tf([100],[1,1,100]);W1=ctrl.tf([.5,5],[1,.05]);W2=.1;W3=.01
K_ms=ctrl.tf([50,50],[1,20,199])
K_ls=20*ctrl.tf([1,10,100],[1,.4,100])
def candidate(a=20.,k=200.):return ctrl.tf(np.array([1.,1.,100.])*k/100,[1.,a,0.])
def response(a=20.,k=200.,rho=.01,wb=5.,freq=w):
    s=1j*np.asarray(freq);D=s*s+a*s+k
    S=s*(s+a)/D;T=k/D;U=k/100*(s*s+s+100)/D;W=(.5*s+wb)/(s+.01*wb)
    return S,T,U,np.sqrt(abs(W*S)**2+.01*abs(T)**2+rho*rho*abs(U)**2)
def rational_peak(N,D):
    stationary=poly.polysub(poly.polymul(poly.polyder(N),D),poly.polymul(N,poly.polyder(D)))
    roots=poly.polyroots(poly.polytrim(stationary,tol=1e-10))
    xs=[0.]+[float(x.real) for x in roots if x.real>0 and abs(x.imag)<1e-7*max(1.,abs(x.real))]
    values=[(np.sqrt(max(0.,poly.polyval(x,N)/poly.polyval(x,D))),np.sqrt(x)) for x in xs]
    values.append((np.sqrt(N[-1]/D[-1]) if len(N)==len(D) else 0.,float('inf')))
    return max(values,key=lambda x:x[0])
def full_peaks(a=20.,k=200.,rho=.01,wb=5.):
    D=np.array([k*k,a*a-2*k,1.]);F=np.array([(.01*wb)**2,1.])
    NS=np.array([0.,a*a,1.]);NU=np.array([10000.,-199.,1.])*(k/100)**2
    N=poly.polyadd(poly.polymul([wb*wb,.25],NS),poly.polymul(F,poly.polyadd([.01*k*k],rho*rho*NU)))
    return {'Ms':rational_peak(NS,D),'gamma':rational_peak(N,poly.polymul(D,F))}
def audit(C,wn=10.):
    P=ctrl.tf([wn*wn],[1,.1*wn,wn*wn]);L=P*C;S=ctrl.feedback(1,L);T=ctrl.feedback(L,1);U=ctrl.feedback(C,P)
    alpha=float(max(ctrl.poles(T).real));stable=alpha<0
    return {'alpha':alpha,'stable':stable,'S_DC_algebra':float(ctrl.dcgain(S)),'S_scan':float(max(abs(S(1j*w)))),'T10':float(abs(T(10j))),'S':S,'T':T,'U':U}

